import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSegmented,
  JxSelect,
  JxSlider,
  JxSwitch,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

interface AppearanceSettingsScreenProps {
  defaultValue?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_OPTIONS: { value: Theme; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const INITIAL: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

export default function AppearanceSettingsScreen({
  defaultValue = INITIAL,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>(defaultValue);

  const update = useCallback(
    <K extends keyof AppearanceSettings>(key: K, value: AppearanceSettings[K]) => {
      setSettings((prev) => {
        const next = { ...prev, [key]: value };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-6)',
        padding: 'var(--jx-space-6)',
        maxWidth: 'var(--jx-size-container-sm, 40rem)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 style={{ margin: 0, font: 'var(--jx-font-heading-md)' }}>Внешний вид</h2>
        <JxBadge variant="neutral">{themeLabel}</JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <label style={{ font: 'var(--jx-font-label-md)' }}>Тема оформления</label>
        <JxSegmented
          value={settings.theme}
          onValueChange={(value: Theme) => update('theme', value)}
          options={THEME_OPTIONS}
          aria-label="Тема оформления"
        />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
          <label style={{ font: 'var(--jx-font-label-md)' }}>Масштаб интерфейса</label>
          <span style={{ font: 'var(--jx-font-body-sm)', color: 'var(--jx-color-text-muted)' }}>
            {settings.scale}%
          </span>
        </div>
        <JxSlider
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value: number) => update('scale', value)}
          aria-label="Масштаб интерфейса в процентах"
        />
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-4)',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
          <span style={{ font: 'var(--jx-font-label-md)' }}>Плотная вёрстка</span>
          <span style={{ font: 'var(--jx-font-body-sm)', color: 'var(--jx-color-text-muted)' }}>
            Уменьшает отступы и высоту строк
          </span>
        </div>
        <JxSwitch
          checked={settings.dense}
          onCheckedChange={(checked: boolean) => update('dense', checked)}
          aria-label="Плотная вёрстка"
        />
      </div>

      <JxDivider />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
        <h3 style={{ margin: 0, font: 'var(--jx-font-heading-sm)' }}>Ещё</h3>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
          <label style={{ font: 'var(--jx-font-label-md)' }}>Шрифт</label>
          <JxSelect
            value={settings.font}
            onValueChange={(value: FontFamily) => update('font', value)}
            options={FONT_OPTIONS}
            aria-label="Шрифт интерфейса"
          />
        </div>
      </div>
    </section>
  );
}

